namespace ghidra.app.plugin.core.debug.service.modules;



using ghidra.app.services;
using ghidra.debug.api.modules.SectionMapProposal;
using ghidra.framework.cmd;
using ghidra.trace.model;
using ghidra.util.exception;
using ghidra.util.task;

public class MapSectionsBackgroundCommand : BackgroundCommand<Trace> {
	private DebuggerStaticMappingService service;
	private Collection<SectionMapEntry> entries;

	public MapSectionsBackgroundCommand(DebuggerStaticMappingService service,
			Collection<SectionMapEntry> entries) : base("Map sections", true, true, true)
    {
		this.service = service;
		this.entries = entries;
	}

	/* @Override */
	public bool applyTo(Trace trace, TaskMonitor monitor) {
		try {
			service.addSectionMappings(entries, monitor, true);
		}
		catch (CancelledException e) {
			return false;
		}
		return true;
	}
}
